import { createCorpus, ingestDocument } from '@projexlight/sdk-knowledge-rag';
const { corpus_id } = await createCorpus({
  tenant_id, name: 'product-docs',
  chunking: { strategy: 'recursive', size_tokens: 800, overlap: 80 },
});
for (const doc of docs) {
  await ingestDocument({ corpus_id, kind: 'markdown', uri: doc.uri });
}

import { retrieve } from '@projexlight/sdk-knowledge-rag';
const { chunks, retrieval_id } = await retrieve({
  tenant_id, persona_id, corpus_id,
  query: 'how do I cancel a subscription mid-cycle?',
  top_k: 6,
});
// pack chunks into a system message; call ai-gateway.complete with retrieval_id in the metadata.

import { retrieve } from '@projexlight/sdk-knowledge-rag';
