// Driven by event subscription:
subscribeEvents('consent.receipt.revoked.v1', async (e) => {
  const docs = await findDocumentsForSubject(e.payload.subject_persona_id);
  for (const doc of docs) await deleteDocument({ document_id: doc.id });
});

